\[
k= \frac{\mathbf{d}_1\cdot\mathbf{d}_2}{\|\mathbf{d}_1\|\|\,\mathbf{d}_2\|}
= \frac{180}{\sqrt{89}\,\sqrt{360}}
= \frac{180}{\sqrt{32280}}
\]

